BEGIN;
SELECT set_config('request.jwt.claim.sub','1ac5f8d8-b2c8-44c0-a7ea-6880ee7b898d',true);
SET LOCAL ROLE authenticated;
INSERT INTO public.productions(id,name,client,created_by) VALUES('p_workflow_rollback','Workflow rollback test','Rollback fixture',auth.uid());
INSERT INTO public.site_document_folders(production_id,path) VALUES('p_workflow_rollback','Source'),('p_workflow_rollback','Source/Nested'),('p_workflow_rollback','Destination');
INSERT INTO public.site_documents(id,production_id,name,path,category) VALUES('00000000-0000-4000-8000-000000000091','p_workflow_rollback','First.pdf','p_workflow_rollback/first.pdf','Source/Nested'),('00000000-0000-4000-8000-000000000092','p_workflow_rollback','Second.pdf','p_workflow_rollback/second.pdf','General');
SELECT public.manage_document_library('p_workflow_rollback','rename','{}',ARRAY['Source'],'','Renamed');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_documents WHERE production_id='p_workflow_rollback' AND category='Renamed/Nested') THEN RAISE EXCEPTION 'Nested folder rename failed'; END IF; END $$;
SELECT public.manage_document_library('p_workflow_rollback','move','{}',ARRAY['Renamed'],'Destination');
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_documents WHERE production_id='p_workflow_rollback' AND category='Destination/Renamed/Nested') THEN RAISE EXCEPTION 'Nested folder move failed'; END IF;
 BEGIN PERFORM public.manage_document_library('p_workflow_rollback','move','{}',ARRAY['Destination'],'Destination/Renamed'); RAISE EXCEPTION 'TEST FAILED cycle allowed'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST FAILED%' THEN RAISE; END IF; END;
END $$;
SELECT public.manage_document_library('p_workflow_rollback','move',ARRAY['00000000-0000-4000-8000-000000000091','00000000-0000-4000-8000-000000000092']::uuid[],'{}','Destination');
SELECT public.manage_document_library('p_workflow_rollback','rename',ARRAY['00000000-0000-4000-8000-000000000091']::uuid[],'{}','Destination','Renamed.pdf');
DO $$ BEGIN IF (SELECT count(*) FROM public.site_documents WHERE production_id='p_workflow_rollback' AND category='Destination')<>2 THEN RAISE EXCEPTION 'Bulk file move failed'; END IF; END $$;
INSERT INTO public.production_locations(id,production_id,label,address) VALUES('00000000-0000-4000-8000-000000000093','p_workflow_rollback','Rollback location','Initial test address');
UPDATE public.production_locations SET address='Persisted test address' WHERE id='00000000-0000-4000-8000-000000000093';
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.production_locations WHERE id='00000000-0000-4000-8000-000000000093' AND address='Persisted test address') THEN RAISE EXCEPTION 'Location update failed'; END IF; END $$;
SELECT public.manage_document_library('p_workflow_rollback','delete',ARRAY['00000000-0000-4000-8000-000000000091','00000000-0000-4000-8000-000000000092']::uuid[],ARRAY['Destination'],'');
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.site_documents WHERE production_id='p_workflow_rollback') OR EXISTS(SELECT 1 FROM public.site_document_folders WHERE production_id='p_workflow_rollback' AND path LIKE 'Destination%') THEN RAISE EXCEPTION 'Bulk delete failed'; END IF;
 BEGIN UPDATE public.production_audit_events SET actor_name='forged' WHERE production_id='p_workflow_rollback'; RAISE EXCEPTION 'TEST FAILED audit editable'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST FAILED%' THEN RAISE; END IF; END;
END $$;
RESET ROLE;
ROLLBACK;
SELECT 'Document nested rename/move, bulk move/delete, cycle protection, location save and immutable audit passed; all rolled back' AS result;
